function buildIndex(dashboards) {
  return dashboards.map((d) => ({ id: d.id, text: d.title.toLowerCase() }))
}

function search(index, query) {
  const q = query.toLowerCase()
  return index.filter((e) => e.text.includes(q)).map((e) => e.id)
}

module.exports = { buildIndex, search }

